import pptx
from pptx.enum.shapes import MSO_SHAPE_TYPE

def inspect_pptx(filename):
    prs = pptx.Presentation(filename)
    print(f"Loaded {filename}")

    for i, slide in enumerate(prs.slides):
        print(f"Slide {i+1}:")
        for shape in slide.shapes:
            print(f"  Shape Type: {shape.shape_type}")
            if shape.has_text_frame:
                print(f"    Text: {shape.text_frame.text}")

            if shape.shape_type == MSO_SHAPE_TYPE.EMBEDDED_OLE_OBJECT:
                print(f"    Found Embedded OLE Object: {shape.name}")
                # We can try to identify if it's excel
                if hasattr(shape, 'ole_format'):
                     print(f"    OLE Format: {shape.ole_format.prog_id}")

if __name__ == "__main__":
    inspect_pptx("input.pptx")

import pptx
from pptx.enum.shapes import MSO_SHAPE_TYPE
import openpyxl
import io

def extract_and_inspect_excel(filename):
    prs = pptx.Presentation(filename)

    for slide in prs.slides:
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.EMBEDDED_OLE_OBJECT:
                if 'Excel' in shape.ole_format.prog_id:
                    print("Found Excel object.")
                    excel_data = shape.ole_format.blob
                    # Save to a temp file to debug if needed, or just load
                    with open("temp.xlsx", "wb") as f:
                        f.write(excel_data)

                    wb = openpyxl.load_workbook(io.BytesIO(excel_data))
                    ws = wb.active
                    print("Sheet content:")
                    for row in ws.iter_rows(values_only=True):
                        print(row)
                    return

if __name__ == "__main__":
    extract_and_inspect_excel("input.pptx")

import pptx
from pptx.enum.shapes import MSO_SHAPE_TYPE

def get_part_name(filename):
    prs = pptx.Presentation(filename)
    for slide in prs.slides:
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.EMBEDDED_OLE_OBJECT:
                if 'Excel' in shape.ole_format.prog_id:
                    print(f"Part name: {shape.ole_format.part.partname}")
                    return

if __name__ == "__main__":
    get_part_name("input.pptx")

import pptx

def inspect_rels(filename):
    prs = pptx.Presentation(filename)
    slide = prs.slides[0]
    print("Relationships for Slide 1:")
    for rel in slide.part.rels.values():
        print(f"RelId: {rel.rId}, Target: {rel.target_ref}, Type: {rel.reltype}")
        if 'oleObject' in rel.reltype:
             print(f"  -> Found OLE Object target: {rel.target_ref}")

if __name__ == "__main__":
    inspect_rels("input.pptx")
